package ama.config.json;
import ama.canonical.*;import ama.config.*;import ama.model.*;import java.util.*;import org.junit.jupiter.api.Test;import static ama.canonical.CanonicalValue.*;import static ama.config.WireValues.*;import static org.junit.jupiter.api.Assertions.*;
/** Pure controlled-provider projection; changed payloads here are not transport or stored-fact proofs. */
class SensitiveProviderProjectionTest extends Task09ControlledProtocolTest {
 Map<String,CanonicalValue> output(boolean retainSecond)throws Exception{return output(retainSecond,false);}
 Map<String,CanonicalValue> output(boolean retainSecond,boolean background)throws Exception{
  var original=wire();var request=ControlledMinutesProtocol.verify(original.body(),original.header());var envelope=fields(BoundedModelJson.parse(original.body(),ControlledMinutesProtocol.MAX_REQUEST),"protocolVersion","logicalBusinessKey","logicalRequestHash","executionRequestHash","executionId","executionNo","payloadSha256","payload");var p=(ObjectValue)envelope.get("payload");var manifest=(ObjectValue)p.entries().stream().filter(e->e.key().equals("inputManifest")).findFirst().orElseThrow().value();var source=(ObjectValue)((Sequence)manifest.entries().stream().filter(e->e.key().equals("sources")).findFirst().orElseThrow().value()).values().getFirst();var alias=source.entries().stream().filter(e->e.key().equals("sourceId")).findFirst().orElseThrow().value();var other=replace(source,"sourceId",string("controlled-second-source"));manifest=replace(manifest,"sources",retainSecond?list(source,other):list(source));p=replace(replace(replace(p,"inputManifest",manifest),"instructionText",string("controlled:rich-output")),"exclusions",object(field("revisionId",string("00000000-0000-4000-8000-000000000001")),field("entries",list(object(field("sourceId",alias),field("locatorId",string("00000000-0000-4000-8000-000000000002")),field("category",string("INTERNAL_BUSINESS_DATA")),field("reasonHash",nil()))))));
  if(background){var primary=replace(source,"role",string("MEETING"));var bg=replace(other,"role",string("BACKGROUND"));manifest=replace(manifest,"sources",list(primary,bg));p=replace(replace(p,"inputManifest",manifest),"exclusions",object(field("revisionId",string("00000000-0000-4000-8000-000000000001")),field("entries",list())));}
  var values=new HashMap<String,CanonicalValue>();for(var e:p.entries())values.put(e.key(),e.value());var method=ControlledMinutesProvider.class.getDeclaredMethod("rich",ControlledMinutesProtocol.VerifiedRequest.class,Map.class);method.setAccessible(true);byte[] bytes=(byte[])method.invoke(null,request,values);return fields(BoundedModelJson.parse(bytes,8388608),"schemaVersion","inputFingerprint","title","body","elements","sensitive","background","sourceRefs","evidence");
 }
 @Test void everyOutputReferenceAndDetectionMustSkipTheExcludedPhysicalSource()throws Exception{var output=output(true);var refs=array(output.get("sourceRefs"));assertEquals(1,refs.size());assertEquals("controlled-second-source",text(fields(refs.getFirst(),"sourceId","locator").get("sourceId")));for(var item:array(output.get("sensitive")))assertEquals(List.of(string("controlled-second-source")),array(fields(item,"key","category","sourceIds").get("sourceIds")));}
 @Test void noEligibleSourceDoesNotInventEvidenceOrKeepSensitiveOrBackgroundReferences()throws Exception{var output=output(false);for(String key:List.of("sourceRefs","evidence","sensitive","background"))assertTrue(array(output.get(key)).isEmpty(),key);assertFalse(text(output.get("body")).isBlank());}
 @Test void backgroundSensitiveDirectoryCanReferenceItsOwnSourceWithoutBodyEvidence()throws Exception{var output=output(true,true);assertEquals(2,array(output.get("sourceRefs")).size());var second=fields(array(output.get("sensitive")).get(1),"key","category","sourceIds");assertEquals(List.of(string("controlled-second-source")),array(second.get("sourceIds")));assertEquals(List.of(string("controlled-second-source")),array(fields(array(output.get("background")).getFirst(),"key","text","sourceIds").get("sourceIds")));for(var item:array(output.get("evidence")))assertFalse(array(fields(item,"target","sourceIds").get("sourceIds")).contains(string("controlled-second-source")));}
}
